function escapeHtml(value) { const s = value == null ? "" : String(value); return s.replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch])); }
function formatPropertyPrice(value) { if (value == null || value === "") return "Price unavailable"; const n = Number(value); return Number.isFinite(n) ? `$${n.toLocaleString()}` : String(value); }
function createPropertySlug(p) { return String(p.id || p.property_id || p.address || "property").replace(/[^a-zA-Z0-9]+/g,"-").replace(/^-|-$/g,"").toLowerCase(); }
function getPropertyByQuery() { const params = new URLSearchParams(window.location.search); const slug = params.get("slug"); const id = params.get("id"); return properties.find(p => String(p.id) === String(id) || createPropertySlug(p) === slug) || null; }
function getSimilarProperties(current, limit=4) { const sameCity=properties.filter(p=>p.id!==current.id&&p.city===current.city); const sameType=sameCity.filter(p=>(p.propertyType||p.type)===(current.propertyType||current.type)); return [...sameType,...sameCity.filter(p=>!sameType.includes(p)),...properties.filter(p=>p.id!==current.id&&!sameCity.includes(p))].slice(0,limit); }
window.properties=properties; window.escapeHtml=escapeHtml; window.formatPropertyPrice=formatPropertyPrice; window.createPropertySlug=createPropertySlug; window.getPropertyByQuery=getPropertyByQuery; window.getSimilarProperties=getSimilarProperties;
